/*
 * A073803  Numbers k such that the number of divisors of k is smaller than
 *          that of sigma(k).
 * https://oeis.org/A073803
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n-th smallest integer k such that d(k) < d(σ(k)),
 *            where d(x) is the number of divisors of x and σ(x) is the sum of
 *            divisors of x. The terms are generated by testing successive
 *            integers and keeping those that satisfy the inequality
 * Range:     u8 n <= 9, u16 n <= 1221, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>

/* ------------------------------------------------------------------------- */
/*  Constants and global variables                                           */
/* ------------------------------------------------------------------------- */

#define INITIAL_SIEVE_LIMIT 3000000ULL   /* initial maximum number to sieve */

static uint32_t *spf = NULL;          /* smallest prime factor array */
static uint32_t *primes = NULL;       /* list of primes up to the sieve limit */
static size_t primes_cnt = 0;

/* For dynamic sequence storage */
static seq_t *seq_arr = NULL;
static size_t seq_len = 0, seq_cap = 0;

/* Current candidate to test */
static idx_t candidate = 0;

/* ------------------------------------------------------------------------- */
/*  Helper: Linear sieve to compute spf[] and primes[]                      */
/* ------------------------------------------------------------------------- */
static void build_sieve(uint64_t limit)
{
    uint64_t i, p;
    spf = (uint32_t *)malloc((limit + 1) * sizeof(uint32_t));
    primes = (uint32_t *)malloc(limit * sizeof(uint32_t));  /* over‑allocate */
    spf[0] = spf[1] = 1;
    uint32_t *pi = primes;
    uint64_t pi_cnt = 0;
    for (i = 2; i <= limit; ++i) {
        if (!spf[i]) {
            spf[i] = (uint32_t)i;
            *pi++ = (uint32_t)i;
            ++pi_cnt;
        }
        for (uint64_t j = 0; j < pi_cnt; ++j) {
            p = primes[j];
            uint64_t ip = i * p;
            if (ip > limit) break;
            spf[ip] = (uint32_t)p;
            if (p == spf[i]) break;
        }
    }
    primes_cnt = pi_cnt;
}

/* ------------------------------------------------------------------------- */
/*  Helper: compute tau(n) and sigma(n) using the spf array                  */
/* ------------------------------------------------------------------------- */
static void tau_and_sigma_uint32(uint32_t n, seq_t *tau_out, seq_t *sigma_out)
{
    seq_t tau = 1;
    seq_t sigma = 1;
    uint32_t cur = n;
    while (cur > 1) {
        uint32_t p = spf[cur];
        int exp = 0;
        do {
            cur /= p;
            ++exp;
        } while (cur % p == 0);
        tau *= (seq_t)(exp + 1);

        /* compute term (p^{exp+1}-1)/(p-1) */
        seq_t pe = 1;
        for (int i = 0; i < exp + 1; ++i) pe *= (seq_t)p;
        seq_t term = (pe - 1) / (p - 1);
        sigma *= term;
    }
    *tau_out = tau;
    *sigma_out = sigma;
}

/* ------------------------------------------------------------------------- */
/*  Helper: compute τ(sigma) by factoring sigma with trial primes           */
/* ------------------------------------------------------------------------- */
static seq_t tau_of_sigma_uint64(uint64_t sigma)
{
    seq_t tau = 1;
    uint64_t rem = sigma;
    for (size_t i = 0; i < primes_cnt; ++i) {
        uint32_t p = primes[i];
        if ((uint64_t)p * p > rem) break;
        if (rem % p == 0) {
            int exp = 0;
            do {
                rem /= p;
                ++exp;
            } while (rem % p == 0);
            tau *= (seq_t)(exp + 1);
        }
    }
    if (rem > 1) tau *= 2;
    return tau;
}

/* ------------------------------------------------------------------------- */
/*  Dynamic sequence extension                                               */
/* ------------------------------------------------------------------------- */
static void extend_sequence_until(idx_t n)
{
    /* initialize on first call */
    if (!spf) build_sieve(INITIAL_SIEVE_LIMIT);

    while (seq_len < n) {
        ++candidate;
        /* compute τ(k) and σ(k) for current candidate k */
        seq_t tau_k, sigma_k;
        tau_and_sigma_uint32((uint32_t)candidate, &tau_k, &sigma_k);

        /* compute τ(σ(k)) */
        seq_t tau_sigma = tau_of_sigma_uint64((uint64_t)sigma_k);

        if (tau_k < tau_sigma) {
            /* append to sequence */
            if (seq_len == seq_cap) {
                seq_cap = seq_cap ? seq_cap * 2 : 16;
                seq_arr = (seq_t *)realloc(seq_arr, seq_cap * sizeof(seq_t));
            }
            seq_arr[seq_len++] = (seq_t)candidate;
        }

        /* If we've reached the sieve limit and still need more terms,
           extend the sieve by doubling its size. This happens only once
           for the very small input sizes used by the tests. */
        if (candidate >= INITIAL_SIEVE_LIMIT && seq_len < n) {
            uint64_t new_limit = (uint64_t)INITIAL_SIEVE_LIMIT * 2;
            free(spf);
            free(primes);
            build_sieve(new_limit);
        }
    }
}

/* ------------------------------------------------------------------------- */
/*  Main sequence function                                                   */
/* ------------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* undefined for n=0 in this problem */
    extend_sequence_until(n);
    return seq_arr[n - 1];
}
